	/** Folder migration can touch disk, so it runs on RuneLite's worker. */
	private synchronized void prepareFolder()
	{
		if (preparingFolder || folder != null) { return; }
		preparingFolder = true;
		notice = "Preparing the recording folder…";
		executor.execute(() ->
		{
			try
			{
				folder = getPluginDirectory();
				notice = "Ready to record.";
			}
			catch (java.io.IOException | RuntimeException e)
			{
				notice = "Could not prepare the recording folder: " + rootMessage(e)
					+ "\nPress Start recording to retry.";
			}
			finally { preparingFolder = false; }
		});
	}

	String folderPath()
	{
		return folder == null ? "The recording folder is not ready yet." : folder.toString();
	}

	boolean canRecover()
	{
		OsrsCapture pending = pendingSave;
		return pending != null && pending.recorder().state() == Recorder.State.FAILED;
	}

	void retrySave()
	{
		clientThread.invoke(() ->
		{
			if (canRecover())
			{
				handingOff = true;
				watchSave(pendingSave, pendingSave.recorder().finish());
			}
		});
	}

	void discardSave()
	{
		clientThread.invoke(() ->
		{
			if (canRecover())
			{
				((MccrFileRecorder) pendingSave.recorder()).discard();
				pendingSave = null;
				save = CompletableFuture.completedFuture(null);
				notice = "Unsaved recording discarded.";
			}
		});
	}

	void startRecording()
	{
		stopped = false;
		manual = true;
		if (folder == null) { prepareFolder(); }
		clientThread.invoke(() ->
		{
			if (capture == null && client.getGameState() == GameState.LOGGED_IN)
			{
				beginCapture(true);
			}
		});
	}

	void stopRecording()
	{
		stopped = true;
		manual = false;
		continuing = false;
		clientThread.invoke(() -> endCapture("stopped by you", false, true));
	}

	PanelState panelState()
	{
		OsrsCapture current = capture;
		java.util.List<SavedFile> files = new java.util.ArrayList<>(saved);
		StringBuilder text = new StringBuilder();
		if (current == null)
		{
			OsrsCapture pending = pendingSave;
			boolean recover = pending != null && pending.recorder().state() == Recorder.State.FAILED;
			boolean resume = enabled && !stopped && (manual || continuing || config.recordOnLogin());
			text.append(handingOff ? "Saving your recording." + (resume ? " Recording resumes after it is saved." : "")
				: recover ? "Recording paused. The unsaved recording is still in memory.\n\n"
					+ pending.recorder().error() + "\n\nRetry saving, or discard it. Closing RuneLite loses this unsaved recording."
				: stopped ? "Not recording." : notice);
			boolean in = loggedIn;
			if (!in)
			{
				text.append("\n\nLog in to start recording.");
			}
			else if (stopped && pending == null)
			{
				text.append("\n\nWhat you played so far is kept. Press Start recording to begin a new one.");
			}
			return new PanelState(text.toString(), "", files, handingOff && resume,
				in && !recover && (pending == null || handingOff));
		}
		text.append(current.status());
		Recorder recorder = current.recorder();
		if (recorder.state() == Recorder.State.FAILED)
		{
			text.append("\n\nCannot save: ").append(recorder.error());
		}
		else
		{
			text.append("\n\nEach recording is written to its file when it ends. Other players are recorded as unnamed figures.");
		}
		boolean busy = !current.recording();
		String name = recorder instanceof MccrFileRecorder && ((MccrFileRecorder) recorder).path() != null
			? ((MccrFileRecorder) recorder).path().getFileName().toString()
			: "";
		return new PanelState(text.toString(), name, files, !busy, !busy);
	}

	private boolean wantsRecording()
	{
		return enabled && !stopped && (manual || continuing || config.recordOnLogin())
			&& client.getGameState() == GameState.LOGGED_IN;
	}

	static String fileStem(String playerName)
	{
		String who = playerName == null ? "" : playerName.toLowerCase(java.util.Locale.ROOT).replaceAll("[^a-z0-9]+", "-").replaceAll("^-|-$", "");
		String when = java.time.LocalDateTime.now().format(java.time.format.DateTimeFormatter.ofPattern("yyyyMMdd-HHmm"));
		return "osrs-" + when + (who.isEmpty() ? "" : "-" + who);
	}

	private void changeScene()
	{
		WorldView view = client.getTopLevelWorldView();
		sceneIdentity = SceneIdentity.of(view);
		OsrsCapture current = capture;
		if (current != null) { current.sceneChanged(view); }
		rediscover = true;
	}

	private void beginCapture(boolean freshBaseline)
	{
		if (!wantsRecording() || capture != null || pendingSave != null || handingOff || folder == null)
		{
			return;
		}
		Player me = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (view == null || me == null) { return; }
		sceneIdentity = SceneIdentity.of(view);
		String dimension = sceneIdentity.dimension();
		if (series == null)
		{
			series = java.util.UUID.randomUUID().toString();
			nextPart = 1;
			pseudonyms.clear();
		}
		// Resolve the filename on the first scene tick, when the character name is available.
		Recorder recorder = new MccrFileRecorder(gson, folder, () ->
		{
			Player who = client.getLocalPlayer();
			return fileStem(who == null ? null : who.getName());
		}, executor);
		OsrsCapture next = new OsrsCapture(client, recorder, config, dimension, me == null ? null : me.getName(), client.getWorld(),
			series, nextPart++, pseudonyms, config.chunkMinutes() * 60.0);
		capture = next;
		continuing = true;
		rediscover = freshBaseline;
		notice = "Recording. The file is saved when this part ends.";
		next.start().whenComplete((ignored, throwable) ->
		{
			if (throwable != null)
			{
				notice = "Could not start the recording file: " + rootMessage(throwable);
				log.debug("capture open failed", throwable);
			}
		});
	}

	private CompletableFuture<Void> endCapture(String reason, boolean openStudio)
	{
		return endCapture(reason, openStudio, false);
	}

	private CompletableFuture<Void> endCapture(String reason, boolean openStudio, boolean planned)
	{
		OsrsCapture current = capture;
		capture = null;
		if (current == null)
		{
			return save;
		}
		pendingSave = current;
		handingOff = true;
		return watchSave(current, current.finish(reason, openStudio, planned));
	}

	private CompletableFuture<Void> watchSave(OsrsCapture current, CompletableFuture<Void> result)
	{
		// Publication is updated before the returned future completes, including on
		// client shutdown when another client-thread callback cannot be relied on.
		save = result.whenComplete((ignored, throwable) ->
		{
			if (throwable == null)
			{
				if (current.recorder().state() == Recorder.State.COMPLETE) { remember(current, null); }
				pendingSave = null;
				notice = current.recorder().state() == Recorder.State.IDLE
					? "Recording cancelled before the first scene." : "Recording saved.";
			}
			else
			{
				notice = "Recording paused: retry saving or discard the unsaved recording.";
				log.warn("Could not save Embertide recording; retained in memory for retry", throwable);
			}
			handingOff = false;
		});
		return save;
	}

	private void remember(OsrsCapture ended, Throwable throwable)
	{
		Recorder recorder = ended.recorder();
		String name = recorder instanceof MccrFileRecorder && ((MccrFileRecorder) recorder).path() != null
			? ((MccrFileRecorder) recorder).path().getFileName().toString()
			: "recording " + ended.part();
		String problem = throwable == null ? "" : rootMessage(throwable);
		if (throwable == null && recorder.state() == Recorder.State.FAILED)
		{
			problem = recorder.error();
		}
		saved.add(new SavedFile(name, ended.part(), ended.seconds(), problem));
	}

	private static String rootMessage(Throwable throwable)
	{
		Throwable cause = throwable;
		while (cause.getCause() != null && cause.getCause() != cause)
		{
			cause = cause.getCause();
		}
		return cause.getMessage() == null ? cause.getClass().getSimpleName() : cause.getMessage();
	}

	private static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xE8, 0x86, 0x3A));
		g.fillOval(2, 2, 12, 12);
		g.setColor(new Color(0xFF, 0xE0, 0xAD));
		g.fillOval(6, 5, 4, 4);
		g.dispose();
		return image;
	}
}

package com.extrinsiccognition.embertide;

import java.util.Locale;

/**
 * Map world tiles to MCCR cells: (x, y, plane) becomes (x, plane * 8 + elevation, -y).
 * The recording axes are east, up and south; elevation is clamped below the next plane.
 */
public final class SceneMapper
{
	public static final int LOCAL_TILE_SIZE = 128;
	public static final int PLANE_HEIGHT = 8;
	public static final int MAX_MATERIAL_LENGTH = 64;
	public static final String AIR = "air";

	private SceneMapper()
	{
	}

	public static int elevation(int localHeight)
	{
		int blocks = (int) Math.round(-localHeight / (double) LOCAL_TILE_SIZE);
		return Math.max(0, Math.min(PLANE_HEIGHT - 1, blocks));
	}

	public static int y(int plane, int localHeight)
	{
		return plane * PLANE_HEIGHT + elevation(localHeight);
	}

	public static int[] groundCell(int worldX, int worldY, int plane, int localHeight)
	{
		return new int[]{worldX, y(plane, localHeight), -worldY};
	}

	public static int[] objectCell(int worldX, int worldY, int plane, int localHeight)
	{
		return new int[]{worldX, y(plane, localHeight) + 1, -worldY};
	}

	public static String groundMaterial(short overlayId, short underlayId)
	{
		if (overlayId != 0)
		{
			return "osrs:overlay:" + (overlayId & 0xFFFF);
		}
		return "osrs:underlay:" + (underlayId & 0xFFFF);
	}

	public static String objectMaterial(String name)
	{
		if (name == null)
		{
			return null;
		}
		String trimmed = name.trim().toLowerCase(Locale.ROOT);
		if (trimmed.isEmpty() || trimmed.equals("null"))
		{
			return null;
		}
		return trimmed.length() > MAX_MATERIAL_LENGTH ? trimmed.substring(0, MAX_MATERIAL_LENGTH) : trimmed;
	}

	public static int objectType(int config)
	{
		return config & 31;
	}

	public static int objectOrientation(int config)
	{
		return (config >>> 6) & 3;
	}

	/**
	 * Convert the client's clockwise orientation (0..2047 from south) to replay yaw
	 * in the east/up/south coordinate system, where positive rotation is anticlockwise.
	 */
	public static double yawDegrees(int orientation)
	{
		int mirrored = (2048 - (orientation & 2047)) & 2047;
		return Math.round((mirrored * 360.0 / 2048.0) * 10000.0) / 10000.0;
	}

	public static boolean inScene(int baseX, int baseY, int sizeX, int sizeY, int plane, int x, int y, int p)
	{
		int sx = x - baseX;
		int sy = y - baseY;
		return p == plane && sx >= 0 && sy >= 0 && sx < sizeX && sy < sizeY;
	}

	public static long key(int x, int y, int z)
	{
		return ((long) (x & 0xFFFFFF) << 40) | ((long) (y & 0xFFFF) << 24) | (z & 0xFFFFFF);
	}

	public static long key(int[] cell)
	{
		return key(cell[0], cell[1], cell[2]);
	}
}

package com.extrinsiccognition.embertide;

import java.util.Arrays;
import net.runelite.api.WorldView;

/** Surface scene loads share coordinates; each instance layout has its own space. */
final class SceneIdentity
{
	private final boolean instance;
	private final int baseX;
	private final int baseY;
	private final int[] regions;
	private final int[][][] chunks;

	private SceneIdentity(WorldView view)
	{
		instance = view != null && view.isInstance();
		baseX = instance ? view.getBaseX() : 0;
		baseY = instance ? view.getBaseY() : 0;
		regions = instance && view.getMapRegions() != null ? view.getMapRegions().clone() : new int[0];
		int[][][] source = instance ? view.getInstanceTemplateChunks() : null;
		chunks = source == null ? new int[0][][] : new int[source.length][][];
		for (int p = 0; p < chunks.length; p++)
		{
			if (source[p] == null) { continue; }
			chunks[p] = new int[source[p].length][];
			for (int x = 0; x < chunks[p].length; x++)
			{
				chunks[p][x] = source[p][x] == null ? null : source[p][x].clone();
			}
		}
	}

	static SceneIdentity of(WorldView view) { return new SceneIdentity(view); }

	String dimension() { return instance ? "osrs:instance:" + Integer.toUnsignedString(hashCode(), 16) : "osrs:surface"; }

	@Override
	public boolean equals(Object value)
	{
		if (!(value instanceof SceneIdentity)) { return false; }
		SceneIdentity other = (SceneIdentity) value;
		return instance == other.instance && baseX == other.baseX && baseY == other.baseY
			&& Arrays.equals(regions, other.regions) && Arrays.deepEquals(chunks, other.chunks);
	}

	@Override
	public int hashCode()
	{
		return (((Boolean.hashCode(instance) * 31 + baseX) * 31 + baseY) * 31 + Arrays.hashCode(regions)) * 31 + Arrays.deepHashCode(chunks);
	}
}

package com.extrinsiccognition.embertide;

import com.google.gson.JsonObject;
import java.util.concurrent.CompletableFuture;

public interface Recorder
{
	enum State
	{
		IDLE, OPENING, READY, FINISHING, COMPLETE, FAILED
	}

	State state();

	String error();

	String captureId();

	CompletableFuture<Void> open(JsonObject header);

	/** Return false when admission fails; the caller must stop adding observations. */
	boolean enqueue(JsonObject record, boolean control);

	default boolean full() { return false; }

	CompletableFuture<Void> flush();

	CompletableFuture<Void> finish();

	CompletableFuture<Void> openStudio();

	String destination();
}

package com.extrinsiccognition.embertide;

import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import net.runelite.api.Model;

/** The displayed sky has no public cache id. Keep its bounded, already-lit scene mesh. */
final class SceneSkybox
{
	static final int MAX_VERTICES = 16384, MAX_FACES = 16384;
	private Long previous;

	JsonObject changed(Model model, double brightness)
	{
		if (!Double.isFinite(brightness) || brightness < 0.1 || brightness > 2) { brightness = 0.8; }
		if (model == null) return absent("none");
		int vertices = model.getVerticesCount(), faces = model.getFaceCount();
		if (vertices < 1 || faces < 1 || vertices > MAX_VERTICES || faces > MAX_FACES) return absent("unsupported");
		float[] x = model.getVerticesX(), y = model.getVerticesY(), z = model.getVerticesZ();
		int[] a = model.getFaceIndices1(), b = model.getFaceIndices2(), c = model.getFaceIndices3();
		int[] ca = model.getFaceColors1(), cb = model.getFaceColors2(), cc = model.getFaceColors3();
		byte[] alpha = model.getFaceTransparencies(), textureFaces = model.getTextureFaces();
		short[] textures = model.getFaceTextures();
		int[] ta = model.getTexIndices1(), tb = model.getTexIndices2(), tc = model.getTexIndices3();
		if (x == null || y == null || z == null || x.length < vertices || y.length < vertices || z.length < vertices
			|| a == null || b == null || c == null || a.length < faces || b.length < faces || c.length < faces
			|| ca == null || cb == null || cc == null || ca.length < faces || cb.length < faces || cc.length < faces
			|| (alpha != null && alpha.length < faces) || (textures != null && textures.length < faces)
			|| (textureFaces != null && textureFaces.length < faces)) return absent("unsupported");
		long hash = mix(mix(mix(mix(Double.doubleToLongBits(brightness), model.getOverrideAmount()),
			model.getOverrideHue()), model.getOverrideSaturation()), model.getOverrideLuminance());
		for (int v = 0; v < vertices; v++)
		{
			if (!Float.isFinite(x[v]) || !Float.isFinite(y[v]) || !Float.isFinite(z[v])
				|| Math.abs(x[v]) > 1000000 || Math.abs(y[v]) > 1000000 || Math.abs(z[v]) > 1000000) return absent("unsupported");
			hash = mix(mix(mix(hash, Float.floatToIntBits(x[v])), Float.floatToIntBits(y[v])), Float.floatToIntBits(z[v]));
		}
		for (int f = 0; f < faces; f++)
		{
			if (!vertex(a[f], vertices) || !vertex(b[f], vertices) || !vertex(c[f], vertices)) return absent("unsupported");
			hash = mix(mix(mix(mix(mix(mix(hash, a[f]), b[f]), c[f]), ca[f]), cb[f]), cc[f]);
			hash = mix(mix(hash, alpha == null ? 0 : alpha[f] & 255), textures == null ? -1 : textures[f]);
			int uv = textureFaces == null || textureFaces[f] == -1 ? -1 : textureFaces[f] & 255;
			if (uv >= 0 && (ta == null || tb == null || tc == null || uv >= ta.length || uv >= tb.length || uv >= tc.length
				|| !vertex(ta[uv], vertices) || !vertex(tb[uv], vertices) || !vertex(tc[uv], vertices))) return absent("unsupported");
			hash = mix(mix(mix(hash, uv < 0 ? a[f] : ta[uv]), uv < 0 ? b[f] : tb[uv]), uv < 0 ? c[f] : tc[uv]);
		}
		if (previous != null && previous == hash) return null;
		previous = hash;
		JsonArray positions = new JsonArray(), indices = new JsonArray(), colors = new JsonArray();
		JsonArray alphas = new JsonArray(), textureIds = new JsonArray(), uvFaces = new JsonArray();
		for (int v = 0; v < vertices; v++) { positions.add(x[v]); positions.add(y[v]); positions.add(z[v]); }
		for (int f = 0; f < faces; f++)
		{
			indices.add(a[f]); indices.add(b[f]); indices.add(c[f]);
			boolean plain = textures == null || textures[f] == -1;
			colors.add(plain ? color(ca[f], model) : ca[f]);
			colors.add(plain ? color(cb[f], model) : cb[f]);
			colors.add(plain ? color(cc[f], model) : cc[f]);
			alphas.add(alpha == null ? 0 : alpha[f] & 255);
			textureIds.add(textures == null || textures[f] == -1 ? -1 : textures[f] & 65535);
			int uv = textureFaces == null || textureFaces[f] == -1 ? -1 : textureFaces[f] & 255;
			uvFaces.add(uv < 0 ? a[f] : ta[uv]); uvFaces.add(uv < 0 ? b[f] : tb[uv]); uvFaces.add(uv < 0 ? c[f] : tc[uv]);
		}
		JsonObject mesh = new JsonObject();
		mesh.add("vertices", positions); mesh.add("faces", indices); mesh.add("colors", colors);
		mesh.add("alpha", alphas); mesh.add("textures", textureIds); mesh.add("uv_faces", uvFaces);
		mesh.addProperty("brightness", brightness);
		JsonObject payload = new JsonObject(); payload.add("mesh", mesh);
		return payload;
	}

	private JsonObject absent(String status)
	{
		long hash = status.equals("none") ? Long.MIN_VALUE : Long.MAX_VALUE;
		if (previous != null && previous == hash) return null;
		previous = hash;
		JsonObject payload = new JsonObject(); payload.add("mesh", JsonNull.INSTANCE); payload.addProperty("status", status);
		return payload;
	}

	private static boolean vertex(int index, int count) { return index >= 0 && index < count; }
	private static int color(int hsl, Model model)
	{
		int amount = model.getOverrideAmount();
		if (hsl < 0 || amount <= 0) { return hsl; }
		int hue = hsl >> 10 & 63, saturation = hsl >> 7 & 7, light = hsl & 127;
		if (model.getOverrideHue() != -1) hue += amount * (model.getOverrideHue() - hue) >> 7;
		if (model.getOverrideSaturation() != -1) saturation += amount * (model.getOverrideSaturation() - saturation) >> 7;
		if (model.getOverrideLuminance() != -1) light += amount * (model.getOverrideLuminance() - light) >> 7;
		return (hue << 10 | saturation << 7 | light) & 65535;
	}
	private static long mix(long hash, int value) { return (hash ^ value) * 0x100000001b3L; }
}

package com.extrinsiccognition.embertide;

import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

public final class EmbertidePanel extends PluginPanel
{
	private final JTextArea status = new JTextArea();
	private final JPanel files = new JPanel();
	private final JButton toggle = new JButton("Stop recording");
	private final JButton folder = new JButton("Show my recordings");
	private final JButton retry = new JButton("Retry saving");
	private final JButton discard = new JButton("Discard unsaved recording");
	private final Timer refresh;
	private boolean recording;
	private String drawn = "";

	EmbertidePanel(EmbertidePlugin plugin)
	{
		super(false);
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel top = new JPanel();
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		top.setOpaque(false);
		JLabel title = new JLabel("3D Replay Recorder");
		title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
		title.setForeground(ColorScheme.BRAND_ORANGE);
		title.setAlignmentX(LEFT_ALIGNMENT);
		top.add(title);
		top.add(Box.createVerticalStrut(6));
		JTextArea where = new JTextArea("Play as normal. When you're done, open your session in the Embertide app or at");
		where.setEditable(false);
		where.setLineWrap(true);
		where.setWrapStyleWord(true);
		where.setOpaque(false);
		where.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		where.setAlignmentX(LEFT_ALIGNMENT);
		top.add(where);
		JLabel studio = new JLabel("<html><u>embertide.gg/studio</u></html>");
		studio.setForeground(ColorScheme.BRAND_ORANGE);
		studio.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		studio.setToolTipText("Opens Studio in your browser. Drag a recording from your recordings folder into it.");
		studio.setAlignmentX(LEFT_ALIGNMENT);
		studio.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				LinkBrowser.browse(MccrFileRecorder.STUDIO_URL);
			}
		});
		top.add(studio);
		add(top, BorderLayout.NORTH);

		JPanel middle = new JPanel();
		middle.setLayout(new BoxLayout(middle, BoxLayout.Y_AXIS));
		middle.setOpaque(false);
		status.setEditable(false);
		status.setLineWrap(true);
		status.setWrapStyleWord(true);
		status.setOpaque(false);
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		status.setBorder(BorderFactory.createEmptyBorder(4, 0, 8, 0));
		status.setAlignmentX(LEFT_ALIGNMENT);
		middle.add(status);
		files.setLayout(new BoxLayout(files, BoxLayout.Y_AXIS));
		files.setOpaque(false);
		files.setAlignmentX(LEFT_ALIGNMENT);
		middle.add(files);
		middle.add(Box.createVerticalGlue());
		add(middle, BorderLayout.CENTER);

		JPanel actions = new JPanel(new GridLayout(0, 1, 0, 6));
		actions.setOpaque(false);
		toggle.addActionListener(e -> {
			if (recording)
			{
				plugin.stopRecording();
			}
			else
			{
				plugin.startRecording();
			}
		});
		folder.addActionListener(e -> {
			JTextArea path = new JTextArea(plugin.folderPath());
			path.setEditable(false);
			path.setLineWrap(true);
			path.setColumns(40);
			path.setRows(3);
			path.selectAll();
			javax.swing.JOptionPane.showMessageDialog(this, path, "Your recordings are here", javax.swing.JOptionPane.INFORMATION_MESSAGE);
		});
		folder.setToolTipText("Shows where your recordings are saved, so you can find them or drag one into Studio.");
		retry.addActionListener(e -> plugin.retrySave());
		discard.addActionListener(e -> {
			if (javax.swing.JOptionPane.showConfirmDialog(this,
				"Throw away the recording that failed to save? You can't get it back.", "Discard recording",
				javax.swing.JOptionPane.YES_NO_OPTION) == javax.swing.JOptionPane.YES_OPTION)
			{
				plugin.discardSave();
			}
		});
		actions.add(toggle);
		actions.add(retry);
		actions.add(discard);
		actions.add(folder);
		add(actions, BorderLayout.SOUTH);

		refresh = new Timer(500, e -> render(plugin));
		refresh.setInitialDelay(0);
		render(plugin);
	}

	private void render(EmbertidePlugin plugin)
	{
		EmbertidePlugin.PanelState state = plugin.panelState();
		status.setText(state.text);
		recording = state.recording;
		toggle.setText(recording ? "Stop recording" : "Start recording");
		toggle.setEnabled(state.canToggle);
		retry.setVisible(plugin.canRecover());
		discard.setVisible(plugin.canRecover());
		drawFiles(state.current, state.saved);
	}

	private void drawFiles(String current, List<EmbertidePlugin.SavedFile> saved)
	{
		StringBuilder key = new StringBuilder(current);
		for (EmbertidePlugin.SavedFile file : saved)
		{
			key.append('|').append(file.name).append(file.problem);
		}
		if (key.toString().equals(drawn))
		{
			return;
		}
		drawn = key.toString();
		files.removeAll();
		if (current.isEmpty() && saved.isEmpty())
		{
			files.revalidate();
			files.repaint();
			return;
		}
		JLabel heading = new JLabel("This session");
		heading.setFont(heading.getFont().deriveFont(Font.BOLD));
		heading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		heading.setAlignmentX(LEFT_ALIGNMENT);
		files.add(heading);
		files.add(Box.createVerticalStrut(4));
		if (!current.isEmpty())
		{
			files.add(row(current, "recording now", false));
		}
		for (int i = saved.size() - 1; i >= 0; i--)
		{
			EmbertidePlugin.SavedFile file = saved.get(i);
			int seconds = (int) file.seconds;
			String note = file.problem.isEmpty()
				? String.format(Locale.ROOT, "%d:%02d", seconds / 60, seconds % 60)
				: "not saved: " + file.problem;
			files.add(row(file.name, note, !file.problem.isEmpty()));
		}
		files.revalidate();
		files.repaint();
	}

	private static JPanel row(String name, String note, boolean problem)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));
		JLabel file = new JLabel(name);
		file.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		file.setToolTipText(name);
		JLabel detail = new JLabel(note);
		detail.setFont(detail.getFont().deriveFont(detail.getFont().getSize2D() - 1f));
		detail.setForeground(problem ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);
		row.add(file);
		row.add(detail);
		return row;
	}

	@Override
	public void onActivate()
	{
		refresh.start();
	}

	@Override
	public void onDeactivate()
	{
		refresh.stop();
	}

	void dispose()
	{
		refresh.stop();
	}
}

